      ro: ["Stabilită în 1953 după Războiul din Coreea.", "Aproximativ 250 km lungime și 4 km lățime.", "În ciuda numelui său, este una dintre cele mai militarizate granițe din lume.", "Găzduiește o diversitate surprinzătoare de faună sălbatică."],
